    static void writeOggPage(OutputStream os, int flags, long granule, int serial, int pageSeq, byte[][] packets) throws Exception {
        // Build segment table
        byte[] segTable = new byte[packets.length];
        int totalData = 0;
        for (int i = 0; i < packets.length; i++) {
            segTable[i] = (byte) Math.min(255, packets[i].length);
            if (packets[i].length > 255) {
                // Need multiple segments for large packets
                int extra = (packets[i].length - 1) / 255;
                segTable = new byte[packets.length + extra];
                for (int j = 0; j < packets.length; j++) {
                    int remaining = packets[j].length;
                    int idx = 0;
                    while (remaining > 0) {
                        segTable[idx] = (byte) Math.min(255, remaining);
                        remaining -= 255;
                        idx++;
                    }
                }
            }
            totalData += packets[i].length;
        }
        
        // Write page header
        os.write("OggS".getBytes("US-ASCII")); // capture pattern
        os.write(0); // version
        os.write(flags); // header type flag
        writeLE64(os, granule); // granule position
        writeLE32(os, serial); // bitstream serial
        writeLE32(os, pageSeq); // page sequence number
        writeLE32(os, 0); // CRC (set to 0, simplified)
        os.write(segTable.length); // number of segments
        os.write(segTable); // segment table
        
        // Write packets
        for (byte[] packet : packets) {
            os.write(packet);
        }
    }
    
    static void writeLE32(OutputStream os, int v) throws Exception {
        os.write(v & 0xFF);
        os.write((v >> 8) & 0xFF);
        os.write((v >> 16) & 0xFF);
        os.write((v >> 24) & 0xFF);
    }
    
    static void writeLE64(OutputStream os, long v) throws Exception {
        writeLE32(os, (int)(v & 0xFFFFFFFFL));
        writeLE32(os, (int)((v >> 32) & 0xFFFFFFFFL));
    }
